/* HARDGATE — build stamp. Single source of truth for "which version am I running?"
   Loaded FIRST so every later script can read G.HG_BUILD. */
(function(){
'use strict';
var G = (typeof window !== 'undefined') ? window : globalThis;

var HG_BUILD = {
  version: 'hg-v913',
  pack: 'THE GOLD DESKS READ THE RECORDS THEY WRITE. Thirteen of the fifteen gold tabs that can be driven write a forward record on every scan. FOUR read any back - omnigold, omnigold1, golddirection, 80percent. NINE wrote into a log that, from their own board, may as well not exist: they recorded what they fired, the log settled it, and the desk never asked what happened. GOLDSCALP and GOLDSWING are a partial exception worth naming rather than counting as read: OMNIGOLD pools their records into ITS gate, so they are consulted - by a different desk, for a different board. GOLDULTRA, NEWGOLD, OPTI GOLD and GOLDPRO are pooled by nobody at all. All nine now render their own forward verdict on their own board. WHAT THIS IS NOT: it does not reimplement OMNIGOLD measured-edge gate, which carries all/ticket/gate-clear populations, cross-tab pooling, an effective-n overlap correction and a multiple-comparison bar counted from the horizon table. Two copies of that would be two things to drift. This is the small honest version for the desks that had nothing: what does my own log say about me, and is it enough to say anything. THE ARITHMETIC IS THE REPO OWN. A desk PAYS if its win rate beats the breakeven its own measured R:R implies (1 / (1 + avgRr)) and LOSES if it cannot, both sides Wilson bounds at the accuracy floor z through the same exported hgWilsonLower; anything that straddles, or under 20 settled, is UNMEASURED. Wilson upper is 1 - lower(losses, n) by the symmetry of the interval, VERIFIED to 3.3e-16 across every (w, n) up to 500 rather than assumed, so this repo keeps ONE interval implementation and not two. ONE ROSTER TOO: accuracy-floor.js now exports its pool map and its family resolver, so the new reader resolves the same names and the prefix families (GOLDPINE:*, NEWGOLD:*) expand from the log exactly once. IT REPORTS. A LOSING verdict DEMOTES, never suppresses, and only at OMNIGOLD own EDGE_VETO_SAMPLES bar of 30 settled trades - borrowing that desk threshold is honest where inventing one is not, and a test asserts OMNIGOLD still sets it to 30 so the two cannot silently disagree. UNMEASURED changes nothing at all: an empty log is the normal state of a desk that has not traded, and the note says in as many words that a desk which has not traded is not a desk that has failed. EVERY DEPENDENCY RESOLVES AT CALL TIME, which is load-bearing rather than incidental: index.html loads accuracy-floor AFTER several gold tabs, and a test proves the module loaded FIRST is silent rather than broken and resolves once its dependencies arrive. TWO DRAFTS OF THE TEST CAUGHT THEMSELVES: the first invented a forward-record shape, hgFwdStats counted 0 of them, and the test would have passed on a reader that read nothing - records are now built in the log OWN shape; and a missing-R:R case chose 30 of 60, which sits on breakeven under an assumed 1:1 and reads the same either way, letting a silent default survive a mutation run until the case was changed to 180 of 200. A THIRD SELF-CAUGHT DEFECT: the note percent formatter used a bare isFinite, and isFinite(null) is TRUE while Number(null) is 0, so a missing Wilson bound rendered as a confident 0.0% - precisely the case a fabricated zero would hide. test-null-formatting caught it and the check is typeof-first now. G1-G7, the gold stop floors and ceilings, the cost-reject bar, the suppress, demote and prefer bars, the Wilson lower bound and the 80% accuracy floor are unchanged. Record only, nothing fetched or sent',
  built: '2026-09-20T00:00:00Z'
};

function hgBuildLabel(b){
  b = b || HG_BUILD;
  var v = String(b.version || '').replace(/^hg-/, '');
  var p = b.pack ? ' · ' + b.pack : '';
  return v ? v + p : 'unknown build';
}

function hgBuildParseVersion(text){
  try{
    if (typeof text !== 'string' || !text) return null;
    var m = text.match(/version\s*:\s*['"]([A-Za-z0-9._-]{1,64})['"]/);
    return m ? m[1] : null;
  }catch(e){ return null; }
}

function hgBuildCompare(loaded, live){
  if (!loaded || !live) return { state: 'unknown', reason: 'could not read one side' };
  if (String(loaded) === String(live)) return { state: 'fresh', reason: 'matches server' };
  return { state: 'stale', reason: 'server is on ' + live + ', this tab loaded ' + loaded };
}

function hgBuildDistance(loaded, live){
  try{
    var a = String(loaded || '').match(/(\d+)\s*$/);
    var b = String(live || '').match(/(\d+)\s*$/);
    if (!a || !b) return null;
    return (+b[1]) - (+a[1]);
  }catch(e){ return null; }
}

function hgBuildChipState(res, b){
  b = b || HG_BUILD;
  var label = hgBuildLabel(b);
  if (!res || res.state === 'pending') return { text: label, cls: 'ok', title: 'checking for newer build' };
  if (res.state === 'fresh') return { text: label, cls: 'ok', title: 'running current build (' + res.live + ')' };
  if (res.state === 'stale'){
    var d = hgBuildDistance(res.loaded, res.live);
    var behind = (d != null && d > 0) ? ' (' + d + ' behind)' : '';
    return { text: label + ' · STALE' + behind, cls: 'bad', title: res.reason + ' — hard-reload to pick it up' };
  }
  return { text: label + ' · ?', cls: 'warn', title: (res.reason || 'freshness unknown') + ' — offline or blocked' };
}

function hgBuildFreshness(fetchImpl){
  var f = (typeof fetchImpl === 'function') ? fetchImpl : (typeof G.fetch === 'function' ? G.fetch.bind(G) : null);
  var loaded = HG_BUILD.version;
  if (!f) return Promise.resolve({ state: 'unknown', loaded: loaded, live: null, reason: 'no fetch' });
  var url = './build-stamp.js?fresh=' + Date.now();
  return f(url, { cache: 'no-store' }).then(function(res){
    if (!res || !res.ok) throw new Error('http ' + (res && res.status));
    return res.text();
  }).then(function(text){
    var live = hgBuildParseVersion(text);
    var cmp = hgBuildCompare(loaded, live);
    return { state: cmp.state, loaded: loaded, live: live, reason: cmp.reason };
  }).catch(function(e){
    return { state: 'unknown', loaded: loaded, live: null, reason: (e && e.message) || 'network failed' };
  });
}

function hgBuildSwWaiting(){
  try{
    var sw = G.navigator && G.navigator.serviceWorker;
    if (!sw || !sw.controller) return Promise.resolve(false);
    return sw.getRegistration().then(function(reg){
      return !!(reg && reg.waiting);
    }).catch(function(){ return false; });
  }catch(e){ return Promise.resolve(false); }
}

function hgRenderBuildChip(el, res){
  try{
    var node = el || (G.document && G.document.getElementById('chipBuild'));
    if (!node) return null;
    var st = hgBuildChipState(res);
    node.textContent = '';
    var b = G.document.createElement('b');
    b.textContent = st.text;
    node.appendChild(b);
    node.title = st.title;
    node.className = 'statuschip hg-build-' + st.cls;
    return st;
  }catch(e){ return null; }
}

function hgRenderVerBadge(res){
  try{
    var node = G.document && G.document.getElementById('hgVerBadge');
    if (!node) return null;
    var v = String(HG_BUILD.version || '').replace(/^hg-/, '');
    if (!v){ node.style.display = 'none'; return null; }
    if (res && res.state === 'stale'){
      var d = hgBuildDistance(res.loaded, res.live);
      var behind = (d != null && d > 0) ? ' (' + d + ' behind)' : '';
      node.textContent = v + ' · STALE' + behind;
      node.className = 'verbadge verbadge-stale';
      node.title = (res.reason || 'stale') + ' — reloading…';
      return { stale: true };
    }
    node.textContent = v;
    node.className = 'verbadge';
    node.title = HG_BUILD.version + (HG_BUILD.pack ? (' · ' + HG_BUILD.pack) : '');
    return { stale: false };
  }catch(e){ return null; }
}

function hgBuildMaybeReload(res, storage, reloadFn){
  try{
    if (!res || res.state !== 'stale' || !res.live) return false;
    var store = storage;
    if (!store && G.sessionStorage) store = G.sessionStorage;
    if (!store || typeof store.getItem !== 'function') return false;
    var key = 'hg_build_reload_' + String(res.live);
    if (store.getItem(key)) return false;
    var reload = reloadFn;
    if (!reload && G.location && typeof G.location.reload === 'function') reload = G.location.reload.bind(G.location);
    if (typeof reload !== 'function') return false;
    store.setItem(key, '1');
    reload();
    return true;
  }catch(e){}
  return false;
}

function hgBuildApplyFreshness(res){
  try{
    if (!res) return res;
    hgRenderBuildChip(null, res);
    hgRenderVerBadge(res);
    G.HG_BUILD_FRESHNESS = res;
    hgBuildMaybeReload(res);
    return res;
  }catch(e){ return res; }
}

function hgBuildInit(){
  try{
    hgRenderBuildChip(null, null);
    hgRenderVerBadge(null);
    hgBuildFreshness().then(function(res){
      return hgBuildSwWaiting().then(function(waiting){
        if (waiting && res.state === 'fresh'){
          res = { state: 'stale', loaded: res.loaded, live: res.live, reason: 'new build downloaded' };
        }
        return hgBuildApplyFreshness(res);
      });
    });
    if (G.document && typeof G.document.addEventListener === 'function'){
      G.document.addEventListener('visibilitychange', function(){
        try{
          if (!G.document || G.document.visibilityState !== 'visible') return;
          hgBuildFreshness().then(hgBuildApplyFreshness);
        }catch(e){}
      });
    }
  }catch(e){}
}

G.HG_BUILD = HG_BUILD;
G.hgBuildLabel = hgBuildLabel;
G.hgBuildParseVersion = hgBuildParseVersion;
G.hgBuildCompare = hgBuildCompare;
G.hgBuildDistance = hgBuildDistance;
G.hgBuildChipState = hgBuildChipState;
G.hgBuildFreshness = hgBuildFreshness;
G.hgBuildSwWaiting = hgBuildSwWaiting;
G.hgRenderBuildChip = hgRenderBuildChip;
G.hgRenderVerBadge = hgRenderVerBadge;
G.hgBuildMaybeReload = hgBuildMaybeReload;
G.hgBuildApplyFreshness = hgBuildApplyFreshness;
G.hgBuildInit = hgBuildInit;

try{
  if (G.document){
    if (G.document.readyState === 'loading'){
      G.document.addEventListener('DOMContentLoaded', hgBuildInit);
    } else {
      hgBuildInit();
    }
  }
}catch(e){}

})();
